code.cpp:
class Solution {
public:
    string findDifferentBinaryString(vector<string>& nums) {
        int n = nums.size();
        string result;
        result.reserve(n);
        for (int i = 0; i < n; i++) {
            result.push_back(nums[i][i] == '0' ? '1' : '0');
        }
        return result;
    }
};
